/* eslint-disable no-invalid-this */

'use strict';

// MODULES //

var logger = require( 'debug' );
var isNumberArray = require( '@stdlib/assert/is-number-array' ).primitives;
var isNumber = require( '@stdlib/assert/is-number' ).isPrimitive;
var hasEqualValues = require( '@stdlib/array/base/assert/has-equal-values' );
var copy = require( '@stdlib/array/base/copy' );
var join = require( '@stdlib/array/base/join' );
var format = require( '@stdlib/string/format' );
var prop = require( './properties.js' );


// VARIABLES //

var debug = logger( 'scatterplot:set:'+prop.name );


// MAIN //

/**
* Sets symbol edge widths (in pixels).
*
* ## Notes
*
* -   Providing `undefined` "unsets" symbol edge widths, in which case symbol edges are rendered using the default edge width.
*
* @private
* @param {(Array<number>|number|void)} value - input value
* @throws {TypeError} must be a number, an array of numbers, or undefined
* @returns {void}
*/
function set( value ) {
	var isNum;
	var curr;

	curr = this[ prop.private ];

	// Case: unset the symbol edge widths...
	if ( value === void 0 ) {
		if ( curr === void 0 ) {
			return;
		}
		debug( 'Current value: [%s]. New value: undefined.', join( curr, ', ' ) );

		// Cache the value before updating the scale to ensure consistent state:
		this[ prop.private ] = value;

		// Clear the edge width range, as the scale should no longer resolve values:
		this.edgeWidthScale.range = [];
		return;
	}
	isNum = isNumber( value );
	if ( !isNum && !isNumberArray( value ) ) {
		throw new TypeError( format( 'invalid assignment. `%s` must be a number, an array of numbers, or undefined. Value: `%s`.', prop.name, value ) );
	}
	if ( isNum ) {
		value = [ value ];
	}
	if ( curr === void 0 ) {
		debug( 'Current value: undefined. New value: [%s].', join( value, ', ' ) );
	} else if ( hasEqualValues( value, curr ) ) {
		return;
	} else {
		debug( 'Current value: [%s]. New value: [%s].', join( curr, ', ' ), join( value, ', ' ) );
	}
	// Perform a defensive copy as we will be caching the specified symbol edge widths:
	value = copy( value );

	// Cache the value before updating the scale to ensure consistent state:
	this[ prop.private ] = value;

	// Update the edge width range:
	this.edgeWidthScale.range = value;
}


// EXPORTS //

module.exports = set;
